#' Rj Editor +
#'
#' 
#' @param data .
#' @param code .
#' @param editorState .
#' @param saveEditorScript .
#' @param editorCleared .
#' @param omvFile .
#' @param saveOmvFile .
#' @param previewDataext .
#' @param previewDataextRequest .
#' @param dataextInfo .
#' @param R .
#' @param vars .
#' @param output .
#' @param figWidth .
#' @param figHeight .
#' @param toggle .
#' @param graphicCapture .
#' @return A results object containing:
#' \tabular{llllll}{
#'   \code{results$omvExport} \tab \tab \tab \tab \tab a html \cr
#'   \code{results$dataextPreview} \tab \tab \tab \tab \tab a html \cr
#'   \code{results$createdColumns} \tab \tab \tab \tab \tab an output \cr
#' }
#'
#' @export
Rjp <- function(
    data,
    code = "\nsummary(data)\n",
    editorState,
    saveEditorScript = FALSE,
    editorCleared = FALSE,
    omvFile = NULL,
    saveOmvFile = FALSE,
    previewDataext = FALSE,
    previewDataextRequest = FALSE,
    dataextInfo,
    R = "bundled",
    vars,
    output = "noEcho",
    figWidth = "",
    figHeight = "",
    toggle = FALSE,
    graphicCapture = "") {

    if ( ! requireNamespace("jmvcore", quietly=TRUE))
        stop("Rjp requires jmvcore to be installed (restart may be required)")

    if ( ! missing(vars)) vars <- jmvcore::resolveQuo(jmvcore::enquo(vars))
    if (missing(data))
        data <- jmvcore::marshalData(
            parent.frame(),
            `if`( ! missing(vars), vars, NULL))


    options <- RjpOptions$new(
        code = code,
        editorState = editorState,
        saveEditorScript = saveEditorScript,
        editorCleared = editorCleared,
        omvFile = omvFile,
        saveOmvFile = saveOmvFile,
        previewDataext = previewDataext,
        previewDataextRequest = previewDataextRequest,
        dataextInfo = dataextInfo,
        R = R,
        vars = vars,
        output = output,
        figWidth = figWidth,
        figHeight = figHeight,
        toggle = toggle,
        graphicCapture = graphicCapture)

    analysis <- RjpClass$new(
        options = options,
        data = data)

    analysis$run()

    analysis$results
}

